#include <iostream>
#include <string>
#include <stdexcept>

template<typename T = int, int Capacity = 5>
class BoundedStack {
private:
    static_assert(Capacity > 0, "positive capacity");
    T elements[Capacity];
    int size{0};
public:
    static int totalInstancesCreated;

    BoundedStack() {
        ++totalInstancesCreated;
    }

    bool empty() const { return size == 0; }
    int getSize() const { return size; }

    bool push(const T& value) {
        if (size >= Capacity) return false;
        elements[size++] = value;
        return true;
    }

    T pop() {
        if(empty()) throw std::out_of_range("empty stack");
        return elements[--size];
    }
};

template<typename T, int Capacity>
int BoundedStack<T, Capacity>::totalInstancesCreated = 0;

template<typename T, int Capacity>
void drainStack(BoundedStack<T, Capacity>& st) {
    while (!st.empty()) {
        std::cout << st.pop() << " ";
    }
    std::cout << "\n";
}

int main() {
    // Khoi tao dung kieu mac dinh (T=int, Capacity=5)
    BoundedStack<> defaultIntStack;
    defaultIntStack.push(10);
    defaultIntStack.push(20);
    defaultIntStack.push(30);

    // Khoi tao tuy bien kieu va dung luong nontype
    BoundedStack<std::string, 4> cityStack;
    cityStack.push("Chicago");
    cityStack.push("Denver");
    cityStack.push("London");

    std::cout << "Int stack popped: ";
    drainStack(defaultIntStack);

    std::cout << "City stack popped: ";
    drainStack(cityStack);

    std::cout << "BoundedStack<> instances: " << BoundedStack<>::totalInstancesCreated << "\n";
    std::cout << "BoundedStack<string, 4> instances: " << BoundedStack<std::string, 4>::totalInstancesCreated << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <memory>
#include <utility>
#include <stdexcept>

template<typename T>
class ImprovedStack {
private:
    T* elements;
    int size;
    int capacity;

    void ensureCapacity() {
        if (size >= capacity) {
            const int next = capacity * 2;
            std::unique_ptr<T[]> fresh(new T[next]);
            for(int i=0;i<size;++i)fresh[i]=elements[i];
            delete[] elements; elements=fresh.release(); capacity=next;
        }
    }

public:
    ImprovedStack() : size(0), capacity(4) {
        elements = new T[capacity];
    }

    ImprovedStack(const ImprovedStack& other) : size(other.size), capacity(other.capacity) {
        std::unique_ptr<T[]> fresh(new T[capacity]);
        for (int i = 0; i < size; ++i) fresh[i] = other.elements[i];
        elements = fresh.release();
    }

    ImprovedStack& operator=(ImprovedStack other) { std::swap(elements, other.elements); std::swap(size, other.size); std::swap(capacity, other.capacity); return *this; }

    ~ImprovedStack() {
        delete[] elements;
    }

    bool empty() const { return size == 0; }
    int getSize() const { return size; }
    int getCapacity() const { return capacity; }

    void push(T value) {
        ensureCapacity();
        elements[size++] = value;
    }

    T peek() const {
        if(empty()) throw std::out_of_range("empty stack");
        return elements[size - 1];
    }

    T pop() {
        if(empty()) throw std::out_of_range("empty stack");
        return elements[--size];
    }
};

int main() {
    ImprovedStack<int> s;
    std::cout << "Initial capacity: " << s.getCapacity() << "\n";

    for (int i = 1; i <= 9; ++i) {
        s.push(i * 10);
    }

    std::cout << "Size after 9 pushes: " << s.getSize() << "\n";
    std::cout << "Capacity after expansions: " << s.getCapacity() << "\n";
    std::cout << "Top element (peek): " << s.peek() << "\n";

    // Kiem tra Copy Constructor (Deep copy)
    ImprovedStack<int> clonedStack = s;

    std::cout << "Original stack pop: ";
    while (!s.empty()) {
        std::cout << s.pop() << " ";
    }
    std::cout << "\n";

    std::cout << "Cloned stack size remains: " << clonedStack.getSize() << "\n";
    std::cout << "Cloned stack top: " << clonedStack.peek() << "\n";

    return 0;
}
